def normalize_id(value: int | str | None) -> str:
    if value is None:
        return "missing"
    if isinstance(value, int):
        return f"user-{value}"
    return value.strip().lower()

print(normalize_id(42))
print(normalize_id(" ADA "))
print(normalize_id(None))
```

Each branch removes one possibility, so the final branch is known to contain a string.

```python
def required_text(value: str) -> str:
    return value.upper()

def page_size(limit: int = 20) -> int:
    return limit

def label(value: str | None) -> str:
    return "unknown" if value is None else value

def greeting(name: str | None = None) -> str:
    return "Hello" if name is None else f"Hello, {name}"

print(required_text("ready"))
print(page_size())
print(label(None))
print(greeting())
```

The defaults control omission; the union annotations control whether `None` belongs to the accepted value set.

